import Foundation

// MARK: - Which model to use
//
// Recommends answer models from the household eval's measurements (ModelCatalog.swift, generated by
// eval/household/catalog.py): how well each answers, researches and files, how much memory it
// needs at its peak, and how fast it writes. The best-scoring model that fits this Mac's memory is
// the pick; a model that is much faster and nearly as good is offered beside it.

enum Recommend {
    /// One overall score from the four measurements (weights sum to 1). Research and filing weigh
    /// most: they are what a small model gets wrong, and a wrong filing changes your notes.
    static let weights = (answers: 0.25, research: 0.35, place: 0.25, facts: 0.15)
    /// Points off per account number or name a model wrote into a filing (privacy matters more than speed).
    static let leakPenalty = 2.0
    /// Same memory rule as the eval (memory.py): the GPU may use about 2/3 of RAM, and 4 GB stays
    /// free for macOS and a browser. A model fits under 90% of that budget; up to 100% is "tight".
    static let gpuShare = 2.0 / 3.0
    static let osAndAppsGB = 4.0
    /// A faster model is offered when it writes at least this many times as fast…
    static let fasterBy = 2.0
    /// …and its overall score is within this many points of the pick.
    static let fasterWithin = 15.0

    enum Fit: String { case fits, tight, no, unknown }

    static var thisMacGB: Double { Double(ProcessInfo.processInfo.physicalMemory) / 1_073_741_824 }

    static func budget(_ ramGB: Double) -> Double { min(ramGB * gpuShare, ramGB - osAndAppsGB) }

    static func fit(_ m: ModelScore, ramGB: Double) -> Fit {
        guard let peak = m.peakGB else { return .unknown }
        let b = budget(ramGB)
        return peak <= b * 0.9 ? .fits : peak <= b ? .tight : .no
    }

    /// 0–100, from the measurements a model has (weights renormalised over the ones present).
    static func overall(_ m: ModelScore) -> Double? {
        let parts: [(Double?, Double)] = [(m.answers, weights.answers), (m.research, weights.research),
                                          (m.filingPlace, weights.place), (m.filingFacts, weights.facts)]
        let have = parts.compactMap { v, w in v.map { ($0, w) } }
        guard !have.isEmpty else { return nil }
        let w = have.map(\.1).reduce(0, +)
        return have.map { $0.0 * $0.1 }.reduce(0, +) / w - Double(m.leaks ?? 0) * leakPenalty
    }

    struct Pick {
        let best: ModelScore
        /// Much faster and nearly as good, when there is one.
        let faster: ModelScore?
        let ramGB: Double
        /// One sentence: why this one.
        var why: String {
            var parts: [String] = []
            if let a = best.answers { parts.append(String(format: "answers %.0f%%", a)) }
            if let r = best.research { parts.append(String(format: "hard questions %.0f%%", r)) }
            if let p = best.filingPlace { parts.append(String(format: "filing %.0f%% in the right place", p)) }
            let speed = best.medianSeconds.map { String(format: "; about %.0f s an answer", $0) } ?? ""
            return String(format: "The best scores that fit %.0f GB: ", ramGB) + parts.joined(separator: ", ") + speed + "."
        }
        var fasterWhy: String? {
            guard let f = faster, let fs = f.tokPerSec, let bs = best.tokPerSec, bs > 0,
                  let fo = Recommend.overall(f), let bo = Recommend.overall(best) else { return nil }
            return String(format: "%.0f× faster (%@), scoring %.0f against %.0f overall: a good choice when speed matters more than the last few points.",
                          fs / bs, f.medianSeconds.map { String(format: "about %.0f s an answer", $0) } ?? String(format: "%.0f tok/s", fs), fo, bo)
        }
    }

    /// The pick for a Mac with this much memory: fitting models first, "tight" ones only if nothing fits.
    static func pick(ramGB: Double = thisMacGB) -> Pick? {
        let scored = ModelCatalog.entries.filter { overall($0) != nil }
        var candidates = scored.filter { fit($0, ramGB: ramGB) == .fits }
        if candidates.isEmpty { candidates = scored.filter { fit($0, ramGB: ramGB) == .tight } }
        guard let best = candidates.max(by: { (overall($0) ?? 0) < (overall($1) ?? 0) }) else { return nil }
        let bestScore = overall(best) ?? 0
        let faster = candidates.filter { m in
            guard let s = m.tokPerSec, let b = best.tokPerSec else { return false }
            return m != best && s >= b * fasterBy && (overall(m) ?? 0) >= bestScore - fasterWithin
        }.max { (overall($0) ?? 0) < (overall($1) ?? 0) }
        return Pick(best: best, faster: faster, ramGB: ramGB)
    }

    /// Every measured model, best first, for the full table.
    static var ranked: [ModelScore] {
        ModelCatalog.entries.sorted { (overall($0) ?? -1) > (overall($1) ?? -1) }
    }

    /// "Answers 74% · hard questions 100% · filing 100% · ~31 s an answer · needs 21 GB"
    static func summary(_ m: ModelScore) -> String {
        var parts: [String] = []
        if let a = m.answers { parts.append(String(format: "Answers %.0f%%", a)) }
        if let r = m.research { parts.append(String(format: "hard questions %.0f%%", r)) }
        if let p = m.filingPlace { parts.append(String(format: "filing %.0f%%", p)) }
        if let l = m.leaks, l > 0 { parts.append("\(l) privacy slip\(l == 1 ? "" : "s") in filing") }
        if let t = m.medianSeconds { parts.append(String(format: "~%.0f s an answer", t)) }
        if let g = m.peakGB { parts.append(String(format: "needs %.0f GB", g)) }
        return parts.joined(separator: " · ")
    }

    /// The other models Holdfast uses, and why (from the same eval).
    static let others = [
        ("Search", "Qwen3-Embedding-0.6B with the Qwen3-Reranker-0.6B: with the same answer model, 73% of facts against 59% with EmbeddingGemma and no reranker."),
        ("Transcription", "Parakeet v3: multilingual, about 140× real time on an M1 Max. Parakeet v2 is English-only."),
    ]
}
